import{c as t,Q as a,j as d,m as s}from"./chunks/framework.DVSyX6JR.js";const b=JSON.parse('{"title":"Dense mesh","description":"","frontmatter":{},"headers":[],"relativePath":"docs/dense-mesh.md","filePath":"docs/dense-mesh.md"}'),o={name:"docs/dense-mesh.md"};function r(n,e,i,l,p,c){return a(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="dense-mesh" tabindex="-1">Dense mesh <a class="header-anchor" href="#dense-mesh" aria-label="Permalink to &quot;Dense mesh&quot;">​</a></h1><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><p>In a flood mesh, every repeater re-broadcasts every packet it hears. In a sparse rural area this is exactly what you want — maximum propagation. In a dense urban area it causes too many redundant retransmissions, filling the LoRa channel and slowing the network.</p><p>The Netherlands has many repeaters close together, so this problem shows up quickly. EU868 duty-cycle limits make every unnecessary retransmission expensive.</p><h2 id="dense-stats" tabindex="-1">Dense stats <a class="header-anchor" href="#dense-stats" aria-label="Permalink to &quot;Dense stats&quot;">​</a></h2><p>Before changing anything, check what is actually happening:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get dense.stats</span></span></code></pre></div><p>This shows:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>flood_advert_rx</td><td>Flood adverts received</td></tr><tr><td>flood_advert_fwd</td><td>Flood adverts forwarded</td></tr><tr><td>flood_advert_drop</td><td>Flood adverts dropped</td></tr><tr><td>flood_dup_packets</td><td>Duplicate flood packets seen</td></tr><tr><td>airtime_rx_ms</td><td>Estimated RX airtime (ms)</td></tr><tr><td>airtime_tx_ms</td><td>Estimated TX airtime (ms)</td></tr><tr><td>cad_busy</td><td>CAD / channel-busy events</td></tr><tr><td>density</td><td>Local node density estimate</td></tr><tr><td>congestion</td><td>Channel congestion estimate</td></tr></tbody></table><p>Reset counters with:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>clear dense.stats</span></span></code></pre></div><p>Stats are RAM-only and reset on reboot.</p><h2 id="flood-advert-forwarding" tabindex="-1">Flood advert forwarding <a class="header-anchor" href="#flood-advert-forwarding" aria-label="Permalink to &quot;Flood advert forwarding&quot;">​</a></h2><p>Control how aggressively flood adverts are forwarded:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get flood.advert.base</span></span>
<span class="line"><span>set flood.advert.base &lt;0.0 .. 1.0&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Value</th><th>Effect</th></tr></thead><tbody><tr><td><code>0</code></td><td>Never forward received flood adverts</td></tr><tr><td><code>0.308</code></td><td>Dense-mesh default — reduces forwarding as hop count grows</td></tr><tr><td><code>1</code></td><td>Forward everything (original MeshCore behavior)</td></tr></tbody></table><p>The default is <code>0.308</code>. Existing networks keep working because the default is already applied.</p><h2 id="relay-probability" tabindex="-1">Relay probability <a class="header-anchor" href="#relay-probability" aria-label="Permalink to &quot;Relay probability&quot;">​</a></h2><p>Manually reduce how many flood packets are relayed:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get flood.relay.prob</span></span>
<span class="line"><span>set flood.relay.prob &lt;0 .. 255&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Value</th><th>Effect</th></tr></thead><tbody><tr><td><code>0</code></td><td>Relay nothing</td></tr><tr><td><code>128</code></td><td>Relay approximately half</td></tr><tr><td><code>255</code></td><td>Relay everything allowed (default)</td></tr></tbody></table><h2 id="dynamic-mode" tabindex="-1">Dynamic mode <a class="header-anchor" href="#dynamic-mode" aria-label="Permalink to &quot;Dynamic mode&quot;">​</a></h2><p>Dynamic mode is available but does not yet change behavior automatically. Enable it to collect data:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set flood.dynamic.enable on</span></span></code></pre></div><p>Automatic tuning will be added once enough real-world data has been collected. Default is off.</p>`,25)])])}const m=t(o,[["render",r]]);export{b as __pageData,m as default};
